-- Запись журнала обновлений (ADR 0077): выпуск 48 — заявка на расходники, подбор картриджа по
-- аппарату и списание со склада по факту выдачи. Миграция M13 плана переработки заявок оргтехники
-- (`docs/office-equipment-requests-rework-plan.md`, §5), волна В11.
--
-- Схему миграция не трогает — она только заводит запись выпуска, как 0126, 0128, 0134, 0135, 0140,
-- 0158, 0159, 0160, 0163, 0165, 0168, 0169, 0170, 0173, 0174, 0184, 0189 и 0190 (ADR 0077 §4).
-- Схему этого выпуска меняет соседняя 0186 (строки заявки, составной ключ журнала и два отложенных
-- триггера инварианта выдачи), а справочник наполняет 0192.
--
-- ЗАЧЕМ ОТДЕЛЬНАЯ ЗАПИСЬ, А НЕ ПРАВКА СОРОК ПЯТОЙ. Выпуск 45 (0184) девятым пунктом обещает прямо:
-- «заявки на расходники этим выпуском ещё не заводятся — форма появится следующим». Пункт был
-- правдой на своё число и обязан ею остаться: журнал выпусков — это лента событий, а не текущее
-- состояние портала, и переписанная задним числом строка соврала бы о том, что человек видел
-- вчера. Обещание закрывается новой записью, а не редактурой старой.
--
-- Номер файла и `seq` взяты по факту на момент создания, а не по плану (план их намеренно не
-- проставлял: ориентир устаревал трижды). На 24.08.2026 последняя миграция в дереве — 0192, а
-- последний выпуск — 47 (0190, версия `0.1.40.0134`), отсюда файл 0193 и `seq = 48`. Разойдись эта
-- пара с очередью — накат упёрся бы в первичный ключ `app_releases`.
--
-- Хвост версии — номер ADR решения: работа целиком описана ADR 0133, отсюда `0.1.41.0133`. Тот же
-- хвост, что у выпуска 45, и это не ошибка: решение одно, выкатов у него три, а счётчик выпусков
-- (третья позиция) монотонен и различает их сам.
--
-- Выпуск ТРЕТИЙ ИЗ ТРЁХ (план §2.2), и последний из тех, что видит пользователь. Второй —
-- contract-выпуск: он снимает совместимость со старым кодом, выводит заявки из двух мёртвых
-- статусов и ставит жёсткие связки. Для читателя журнала он не меняет ничего, и записи у него
-- не будет вовсе.
--
-- Пункты писаны от лица того, кто откроет портал утром: как завести заявку на картридж, откуда
-- берётся список позиций, что случится со складом и почему в акте пришлось объяснять расхождение.
-- Устройство — составной ключ журнала, отложенные триггеры, порядок блокировок по возрастанию
-- `consumable_id` — в журнал не выносится: его читают не программисты.

INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  48, '0.1.41.0133', '2026-08-24', 'Картриджи заказывают заявкой, а склад уменьшается сам', '{133}',
  '[
    {"kind":"feature","text":"В заявке на обслуживание оргтехники появился вид: «Ремонт» или «Расходники». Выбирается он первым полем, и от него зависит, о чём форма спросит дальше. Прежде заявка на картридж заводилась ремонтом, а что именно нужно — писали словами в описании"},
    {"kind":"feature","text":"Выбрали аппарат — портал сам подставляет картриджи, которые к нему подходят: связь «модель — расходник» ведётся в справочнике. Если позиция у модели одна, она встаёт в строку сама; если к модели ничего не привязано, об этом сказано прямо, и рядом есть переключатель «показать все позиции»"},
    {"kind":"feature","text":"Строк в заявке несколько: просят и тонер, и барабан одной заявкой. Позиции, уже выбранные в соседних строках, из списка убираются — две строки на один и тот же картридж завести нельзя"},
    {"kind":"feature","text":"В строке видно, сколько этой позиции на складе, — прямо в подписи, вместе с цветом и кодом номенклатуры. Заказывать вслепую больше не нужно"},
    {"kind":"feature","text":"Закрывая работы, исполнитель отмечает, сколько выдал по каждой строке. Умолчание — «сколько просили», и в обычном случае достаточно нажать «Готово». Разошлось с заявкой — портал попросит объяснить: и когда выдали меньше, и когда больше, и когда не выдали вовсе («съездили, а менять не пришлось»)"},
    {"kind":"feature","text":"Со склада списывается ровно то, что отмечено выданным, и списывается в тот момент, когда заявку закрывают работами. Каждое списание попадает в журнал позиции строкой «−2, выдано по СО-1234» — со ссылкой на заявку"},
    {"kind":"feature","text":"Выданное правится и после закрытия работ — до тех пор, пока заявка не закрыта окончательно. Портал показывает, что именно изменится: «спишется со склада 1» или «вернётся на склад 2», — и на склад уходит только разница, а не всё количество заново"},
    {"kind":"improvement","text":"У заявки на расходники нет ни сметы, ни решения ИТ-службы, ни требования приложить акт: картриджи берут со своего склада, платить за них некому и подтверждать нечем. Вместо вкладки «Смета» в карточке стоит «Номенклатура» — что просили, что выдали и почему разошлось"},
    {"kind":"improvement","text":"Не хватило остатка — заявка не закроется, и портал скажет, чего и сколько недостаёт. Отрицательного остатка на складе не бывает: это учётная книга, а не счётчик"},
    {"kind":"improvement","text":"Одна открытая заявка на аппарат считается теперь по видам отдельно: пока идёт ремонт МФУ, заявку на картриджи к нему завести можно. Прежде вторая заявка любого вида упиралась в первую"}
  ]'::jsonb
);
